:root {
  --bg: #f6f5f2;
  --surface: #ffffff;
  --ink: #1b1a17;
  --muted: #5c5850;
  --line: #dcd7cd;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  --focus: #b45309;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --surface: #1d2026;
    --ink: #eceae5;
    --muted: #a9a49a;
    --line: #333841;
    --accent: #2dd4bf;
    --accent-ink: #10221f;
    --focus: #fbbf24;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 46rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.skip-link {
  position: absolute;
  left: -9999px;
}

.skip-link:focus {
  left: 0.5rem;
  top: 0.5rem;
  z-index: 10;
  padding: 0.5rem 0.75rem;
  background: var(--surface);
  border: 2px solid var(--focus);
  border-radius: 0.5rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

:where(a) {
  color: var(--accent);
}

:where(a):hover {
  text-decoration-thickness: 2px;
}

:where(input, textarea, button):focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* ------------------------------------------------------------------- form */

.note-form,
.search-row {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.75rem;
  padding: 1rem 1.1rem 1.2rem;
  margin-bottom: 1.25rem;
}

.form-heading {
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 0.9rem;
}

.field:last-of-type {
  margin-bottom: 1rem;
}

label {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  padding: 0.5rem 0.65rem;
  width: 100%;
}

textarea {
  resize: vertical;
  min-height: 5.5rem;
}

.hint {
  margin: 0;
  font-size: 0.78rem;
  color: var(--muted);
}

button.primary {
  font: inherit;
  font-weight: 600;
  color: var(--accent-ink);
  background: var(--accent);
  border: 1px solid transparent;
  border-radius: 0.5rem;
  padding: 0.5rem 1.1rem;
  cursor: pointer;
}

button.primary:hover {
  filter: brightness(1.08);
}

/* ----------------------------------------------------------------- search */

.search-row {
  padding-bottom: 0.9rem;
}

.search-row .field {
  margin-bottom: 0;
}

.results-line {
  margin: 0.6rem 0 0;
  min-height: 1.2rem;
  font-size: 0.9rem;
  color: var(--muted);
}

.results-line:empty {
  margin: 0;
  min-height: 0;
}

/* ------------------------------------------------------------------- feed */

.feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: 0.75rem;
  padding: 0.9rem 1.1rem 1rem;
}

.note[aria-current="true"] {
  border-left-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--bg);
  flex: none;
}

.note-heading {
  margin: 0;
  font-size: 1.15rem;
  min-width: 0;
}

.note-title {
  font: inherit;
  color: inherit;
  text-align: left;
  background: none;
  border: 0;
  border-radius: 0.35rem;
  padding: 0.1rem 0.2rem;
  margin: -0.1rem -0.2rem;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
}

.note-body {
  margin-top: 0.5rem;
  overflow-wrap: anywhere;
}

.note-meta {
  margin: 0.6rem 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}

.empty {
  margin: 0;
  padding: 1.5rem;
  text-align: center;
  color: var(--muted);
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: 0.75rem;
}

tool_use_result.content:
:root {
  --bg: #f6f5f2;
  --surface: #ffffff;
  --ink: #1b1a17;
  --muted: #5c5850;
  --line: #dcd7cd;
  --accent: #0f766e;
  --accent-ink: #ffffff;
  --focus: #b45309;
  color-scheme: light dark;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #14161a;
    --surface: #1d2026;
    --ink: #eceae5;
    --muted: #a9a49a;
    --line: #333841;
    --accent: #2dd4bf;
    --accent-ink: #10221f;
    --focus: #fbbf24;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font: 16px/1.55 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

#app {
  max-width: 46rem;
  margin: 0 auto;
  padding: 1.5rem 1rem 4rem;
}

.skip-link {
  position: absolute;
  left: -9999px;
}

.skip-link:focus {
  left: 0.5rem;
  top: 0.5rem;
  z-index: 10;
  padding: 0.5rem 0.75rem;
  background: var(--surface);
  border: 2px solid var(--focus);
  border-radius: 0.5rem;
}

.app-header h1 {
  margin: 0;
  font-size: 1.9rem;
  letter-spacing: -0.02em;
}

.tagline {
  margin: 0.25rem 0 1.5rem;
  color: var(--muted);
}

:where(a) {
  color: var(--accent);
}

:where(a):hover {
  text-decoration-thickness: 2px;
}

:where(input, textarea, button):focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

/* ------------------------------------------------------------------- form */

.note-form,
.search-row {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 0.75rem;
  padding: 1rem 1.1rem 1.2rem;
  margin-bottom: 1.25rem;
}

.form-heading {
  margin: 0 0 0.75rem;
  font-size: 1.05rem;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  margin-bottom: 0.9rem;
}

.field:last-of-type {
  margin-bottom: 1rem;
}

label {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.01em;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
textarea {
  font: inherit;
  color: inherit;
  background: var(--bg);
  border: 1px solid var(--line);
  border-radius: 0.5rem;
  padding: 0.5rem 0.65rem;
  width: 100%;
}

textarea {
  resize: vertical;
  min-height: 5.5rem;
}

.hint {
  margin: 0;
  font-size: 0.78rem;
  color: var(--muted);
}

button.primary {
  font: inherit;
  font-weight: 600;
  color: var(--accent-ink);
  background: var(--accent);
  border: 1px solid transparent;
  border-radius: 0.5rem;
  padding: 0.5rem 1.1rem;
  cursor: pointer;
}

button.primary:hover {
  filter: brightness(1.08);
}

/* ----------------------------------------------------------------- search */

.search-row {
  padding-bottom: 0.9rem;
}

.search-row .field {
  margin-bottom: 0;
}

.results-line {
  margin: 0.6rem 0 0;
  min-height: 1.2rem;
  font-size: 0.9rem;
  color: var(--muted);
}

.results-line:empty {
  margin: 0;
  min-height: 0;
}

/* ------------------------------------------------------------------- feed */

.feed {
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.note {
  background: var(--surface);
  border: 1px solid var(--line);
  border-left: 4px solid transparent;
  border-radius: 0.75rem;
  padding: 0.9rem 1.1rem 1rem;
}

.note[aria-current="true"] {
  border-left-color: var(--accent);
  box-shadow: 0 0 0 1px var(--accent);
}

.note-header {
  display: flex;
  align-items: center;
  gap: 0.7rem;
}

.note-avatar {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  object-fit: cover;
  background: var(--bg);
  flex: none;
}

.note-heading {
  margin: 0;
  font-size: 1.15rem;
  min-width: 0;
}

.note-title {
  font: inherit;
  color: inherit;
  text-align: left;
  background: none;
  border: 0;
  border-radius: 0.35rem;
  padding: 0.1rem 0.2rem;
  margin: -0.1rem -0.2rem;
  cursor: pointer;
}

.note-title:hover {
  color: var(--accent);
}

.note-body {
  margin-top: 0.5rem;
  overflow-wrap: anywhere;
}

.note-meta {
  margin: 0.6rem 0 0;
  font-size: 0.78rem;
  color: var(--muted);
}

.empty {
  margin: 0;
  padding: 1.5rem;
  text-align: center;
  color: var(--muted);
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: 0.75rem;
}

