const dir = process.cwd();
const port = 4700 + Math.floor(Math.random() * 200);
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'inherit' });
await new Promise((r) => setTimeout(r, 500));

const browser = await chromium.launch();
const page = await browser.newPage();
page.on('pageerror', (e) => console.log('pageerror:', e.message));

const base = 'http://127.0.0.1:' + port + '/';

await page.goto(base, { waitUntil: 'load' });
const ids = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('order:', ids);

const firstBodyHtml = await page.$eval('article.note[data-note-id="6"] .note-body', el => el.innerHTML);
console.log('note6 body html:', firstBodyHtml);
const linkHref = await page.$eval('article.note[data-note-id="4"] .note-body a', el => el.getAttribute('href'));
console.log('note4 link href:', linkHref);
const boldTag = await page.$eval('article.note[data-note-id="6"] .note-body b', el => el.tagName);
console.log('bold tag found:', boldTag);

await page.fill('#search', 'douro');
await page.waitForTimeout(100);
const resultsLine = await page.$eval('#results-line', el => el.textContent);
console.log('results-line:', JSON.stringify(resultsLine));
const filteredIds = await page.$$eval('#feed article.note', els => els.map(e => e.dataset.noteId));
console.log('filtered ids:', filteredIds);
console.log('hash after search:', await page.evaluate(() => location.hash));

await page.click('article.note[data-note-id="5"] .note-title');
await page.waitForTimeout(100);
console.log('hash after select:', await page.evaluate(() => location.hash));
const ariaCurrent = await page.$eval('article.note[data-note-id="5"]', el => el.getAttribute('aria-current'));
console.log('aria-current on 5:', ariaCurrent);

await page.reload({ waitUntil: 'load' });
