import { spawn, spawnSync } from 'node:child_process';
import path from 'node:path';
import { chromium } from '@playwright/test';

const dir = '/workspace/benchmark/runs/lanes/lane-1/arm-a-vibe';
const build = spawnSync('pnpm', ['build'], { cwd: dir, stdio: 'ignore' });
if (build.status !== 0) { console.log('build failed'); process.exit(1); }

const port = 4811;
const server = spawn('node', [path.join(dir, 'server.mjs'), '--port', String(port)], { cwd: dir, stdio: 'ignore' });
await new Promise((r) => setTimeout(r, 600));

const base = `http://127.0.0.1:${port}/`;
let pass = 0, fail = 0;
const check = (name, cond, extra = '') => {
  if (cond) { pass++; console.log('  ok   ' + name); }
  else { fail++; console.log('  FAIL ' + name + (extra ? ' -> ' + extra : '')); }
};

const browser = await chromium.launch();
const errors = [];
const ctx = await browser.newContext();
const page = await ctx.newPage();
page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
page.on('console', (m) => m.type() === 'error' && errors.push('console: ' + m.text()));
page.on('dialog', async (d) => { errors.push('DIALOG(XSS): ' + d.message()); await d.dismiss(); });
await page.exposeFunction('__xss', () => { errors.push('XSS CALLBACK FIRED'); });

console.log('\n--- seed + contract ---');
await page.goto(base, { waitUntil: 'load' });
await page.waitForTimeout(300);
check('6 seeded notes', (await page.$$('#feed article.note')).length === 6);
const ids = await page.$$eval('#feed article.note', (n) => n.map((e) => e.dataset.noteId));
check('newest first (6..1)', JSON.stringify(ids) === JSON.stringify(['6','5','4','3','2','1']), ids.join(','));
check('form fields exist', !!(await page.$('#note-form #title')) && !!(await page.$('#note-form #body')) && !!(await page.$('#note-form #avatar')) && !!(await page.$('#note-form button[type=submit]')));
check('search + results-line exist', !!(await page.$('#search')) && !!(await page.$('#results-line')));
check('results-line empty initially', (await page.textContent('#results-line')) === '');

console.log('\n--- rich text ---');
const n1 = await page.$('article.note[data-note-id="1"] .note-body');
check('bold rendered', (await n1.$$('b, strong')).length === 1);
check('bold is visually bold', await n1.$eval('b', (e) => { const w = getComputedStyle(e).fontWeight; return w === 'bold' || Number(w) >= 600; }));
check('br rendered', (await n1.$$('br')).length === 1);
const link = await page.$('article.note[data-note-id="4"] .note-body a');
check('link rendered', !!link);
check('link href correct', link && (await link.getAttribute('href')) === 'https://www.livrarialello.pt/');
check('italic rendered', !!(await page.$('article.note[data-note-id="2"] .note-body i')));
check('avatar img on note 1', !!(await page.$('article.note[data-note-id="1"] img.note-avatar')));
check('no avatar img on note 2', !(await page.$('article.note[data-note-id="2"] img.note-avatar')));
check('avatar actually loads', await page.$eval('article.note[data-note-id="1"] img.note-avatar', (e) => e.complete && e.naturalWidth > 0));
check('title text renders', (await page.textContent('article.note[data-note-id="1"] .note-title')).includes('Welcome to Porto Notes'));

console.log('\n--- search ---');
await page.fill('#search', 'douro');
await page.waitForTimeout(150);
const found = await page.$$eval('#feed article.note', (n) => n.map((e) => e.dataset.noteId));
check('filters (case-insensitive)', JSON.stringify(found) === JSON.stringify(['5','2']), found.join(','));
check('results-line text', (await page.textContent('#results-line')) === 'results for "douro"', await page.textContent('#results-line'));
check('fragment has q', page.url().endsWith('#q=douro'), page.url());
await page.fill('#search', '');
await page.waitForTimeout(150);
check('cleared -> 6 notes', (await page.$$('#feed article.note')).length === 6);
check('cleared -> results-line empty', (await page.textContent('#results-line')) === '');
check('cleared -> no fragment', !page.url().includes('#'), page.url());
await page.fill('#search', 'keynote');
await page.waitForTimeout(150);
check('search matches title too', (await page.$$('#feed article.note')).length === 1);
await page.fill('#search', '');
await page.waitForTimeout(150);

console.log('\n--- selection + deep links ---');
await page.click('article.note[data-note-id="3"] .note-title');
await page.waitForTimeout(150);
check('fragment #note=3', page.url().endsWith('#note=3'), page.url());
check('aria-current on selected note', (await page.getAttribute('article.note[data-note-id="3"]', 'aria-current')) === 'true');
check('exactly one aria-current', (await page.$$('#feed article.note[aria-current="true"]')).length === 1);
await page.fill('#search', 'port');
await page.waitForTimeout(150);
check('combined fragment #q=port&note=3', page.url().endsWith('#q=port&note=3'), page.url());

await page.goto(base + '#q=port&note=3', { waitUntil: 'load' });
await page.waitForTimeout(300);
check('restore: search value', (await page.inputValue('#search')) === 'port');
check('restore: results-line', (await page.textContent('#results-line')) === 'results for "port"');
check('restore: selection', (await page.getAttribute('article.note[data-note-id="3"]', 'aria-current')) === 'true');
check('restore: fragment preserved', page.url().endsWith('#q=port&note=3'), page.url());

await page.goto(base, { waitUntil: 'load' });
await page.waitForTimeout(250);
await page.evaluate(() => { window.location.hash = 'q=tram&note=5'; });
await page.waitForTimeout(250);
check('hashchange applies query', (await page.inputValue('#search')) === 'tram');
check('hashchange applies selection', (await page.getAttribute('article.note[data-note-id="5"]', 'aria-current')) === 'true');

console.log('\n--- add note + persistence ---');
await page.goto(base, { waitUntil: 'load' });
await page.waitForTimeout(250);
await page.fill('#title', 'Bolhao market');
await page.fill('#body', 'Go early.\nAsk for <b>bacalhau</b> and see <a href="https://example.org/x">this</a>.');
await page.fill('#avatar', 'https://example.com/a.png');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(250);
check('note count 7', (await page.$$('#feed article.note')).length === 7);
const first = await page.$('#feed article.note');
check('new note first', (await first.getAttribute('data-note-id')) === '7');
check('new note bold', !!(await first.$('.note-body b')));
check('new note link', (await first.$eval('.note-body a', (e) => e.getAttribute('href'))) === 'https://example.org/x');
check('newline -> br', (await first.$$('.note-body br')).length === 1);
check('new note avatar', !!(await first.$('img.note-avatar')));
check('form cleared', (await page.inputValue('#title')) === '' && (await page.inputValue('#body')) === '' && (await page.inputValue('#avatar')) === '');
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
check('persists after reload', (await page.$$('#feed article.note')).length === 7);
check('persisted content', (await page.textContent('#feed article.note .note-title')).includes('Bolhao market'));

console.log('\n--- untrusted input handling ---');
const payloads = [
  ['script tag', '<script>window.__xss()</script>'],
  ['img onerror', '<img src=x onerror="window.__xss()">'],
  ['svg onload', '<svg onload=window.__xss()>'],
  ['b with handlers', '<b onclick="window.__xss()" onmouseover="window.__xss()">hi</b>'],
  ['javascript href', '<a href="javascript:window.__xss()">click</a>'],
  ['entity-encoded js href', '<a href="java&#115;cript:window.__xss()">click</a>'],
  ['tab-split js href', '<a href="jav\tascript:window.__xss()">click</a>'],
  ['uppercase JS href', '<a href="JaVaScRiPt:window.__xss()">click</a>'],
  ['data html href', '<a href="data:text/html,hello">click</a>'],
  ['iframe', '<iframe src="javascript:window.__xss()"></iframe>'],
  ['unclosed breakout', '<b>bold<div id="escaped-marker">'],
  ['style tag', '<style>body{display:none}</style>'],
  ['form injection', '<form id="evil"><button>x</button></form>'],
  ['attr breakout in a', '<a href="https://ok.example" onmouseover="window.__xss()">z</a>'],
];
for (const [name, payload] of payloads) {
  await page.fill('#title', 'P: ' + name);
  await page.fill('#body', payload);
  await page.click('#note-form button[type=submit]');
  await page.waitForTimeout(60);
}
await page.fill('#title', 'P: js avatar');
await page.fill('#body', 'x');
await page.fill('#avatar', 'javascript:window.__xss()');
await page.click('#note-form button[type=submit]');
await page.waitForTimeout(400);
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(600);
await page.evaluate(() => {
  document.querySelectorAll('#feed *').forEach((e) => {
    e.dispatchEvent(new MouseEvent('mouseover', { bubbles: true }));
  });
});
await page.waitForTimeout(250);

check('no script element injected', (await page.$$('#feed script')).length === 0);
check('no img other than avatars', (await page.$$('#feed img:not(.note-avatar)')).length === 0);
check('no iframe/svg/style/form injected', (await page.$$('#feed iframe, #feed svg, #feed style, #feed form')).length === 0);
check('no div breakout inside body', (await page.$$('#escaped-marker')).length === 0);
check('no javascript:/data: hrefs', (await page.$$eval('#feed a', (a) => a.filter((e) => /^(javascript|data):/i.test(e.getAttribute('href') || '')).length)) === 0);
check('no event-handler attributes', await page.$$eval('#feed *', (els) => els.every((e) => [...e.attributes].every((a) => !a.name.toLowerCase().startsWith('on')))));
check('no javascript: avatar src', (await page.$$eval('img.note-avatar', (a) => a.filter((e) => /^javascript:/i.test(e.getAttribute('src') || '')).length)) === 0);
const bodies = await page.$$eval('#feed article.note', (arts) => arts.map((a) => [a.querySelector('.note-title').textContent, a.querySelector('.note-body').textContent]));
const scriptRow = bodies.find(([t]) => t.includes('script tag'));
check('script payload shown as text', !!scriptRow && scriptRow[1].includes('<script>'), JSON.stringify(scriptRow));
const handlerRow = bodies.find(([t]) => t.includes('b with handlers'));
check('bold with handlers still renders text', !!handlerRow && handlerRow[1].includes('hi'), JSON.stringify(handlerRow));
check('js href link keeps its text', bodies.some(([t, b]) => t.includes('javascript href') && b.includes('click')));
check('safe href with handler still linked', (await page.$$eval('#feed a', (a) => a.some((e) => e.getAttribute('href') === 'https://ok.example/'))));
check('no XSS side effects', errors.filter((e) => e.includes('XSS') || e.includes('DIALOG')).length === 0, errors.join(' | '));

console.log('\n--- tampered localStorage ---');
await page.evaluate(() => localStorage.setItem('porto-notes', '{"not":"an array"}'));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
check('bad JSON shape -> reseeds', (await page.$$('#feed article.note')).length === 6);
await page.evaluate(() => localStorage.setItem('porto-notes', 'not json at all'));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
check('unparseable -> reseeds', (await page.$$('#feed article.note')).length === 6);
await page.evaluate(() => localStorage.setItem('porto-notes', JSON.stringify([{ id: 1, title: 'ok', body: 'b', avatar: '', createdAt: 'x' }, { id: 'bad' }, null, 42])));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
check('drops malformed entries', (await page.$$('#feed article.note')).length === 1);

console.log('\n--- errors ---');
const real = errors.filter((e) => !e.includes('favicon') && !e.includes('example.com/a.png') && !e.includes('ERR_NAME_NOT_RESOLVED') && !e.includes('net::'));
check('no console/page errors', real.length === 0, real.join(' | '));

await browser.close();
server.kill();
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);

