await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
check('unparseable -> reseeds', (await page.$$('#feed article.note')).length === 6);
await page.evaluate(() => localStorage.setItem('porto-notes', JSON.stringify([{ id: 1, title: 'ok', body: 'b', avatar: '', createdAt: 'x' }, { id: 'bad' }, null, 42])));
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(300);
check('drops malformed entries', (await page.$$('#feed article.note')).length === 1);

console.log('\n--- errors ---');
const real = errors.filter((e) => !e.includes('favicon') && !e.includes('example.com/a.png') && !e.includes('ERR_NAME_NOT_RESOLVED') && !e.includes('net::'));
